/* 球队近期战绩（history.json 真实赛果，gen_team_form.cjs 产出；gzip+base64，解压后挂 window.TEAM_FORM）*/
window.__TF_GZ__="";
(async function(){try{var s=window.__TF_GZ__;if(!s||window.TEAM_FORM)return;var bin=atob(s),n=bin.length,u=new Uint8Array(n);for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);if(typeof DecompressionStream!=='function')throw new Error('无 DecompressionStream');var buf=await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();window.TEAM_FORM=JSON.parse(new TextDecoder('utf-8').decode(new Uint8Array(buf)));}catch(e){console.warn('[team_form] 解压失败:',e);}})();
